def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    if n == 1:
        return 'C'
    if n == 2:
        if history[1][1] == 'C':
            return 'D'
        return 'C'
    if n == 99:
        return 'D'
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        return 'D'
    return 'C'
